package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/prescription") public class PrescriptionController{private final PrescriptionService s;public PrescriptionController(PrescriptionService s){this.s=s;}@PostMapping public ResponseEntity<PrescriptionDTO> create(@Valid @RequestBody PrescriptionDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<PrescriptionDTO> all(){return s.all();}@GetMapping("/{id}") public PrescriptionDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public PrescriptionDTO update(@PathVariable Long id,@Valid @RequestBody PrescriptionDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
